fn all_characters_same(s: &[u8]) -> bool {
    if let Some(&first) = s.first() {
        for &b in s.iter().skip(1) {
            if b != first {
                return false;
            }
        }
    }
    true
}

// Example usage and tests
fn main() {
    let cases: &[(&[u8], bool)] = &[
        (b"", true),
        (b"a", true),
        (b"aaaaaa", true),
        (b"ababab", false),
        (b"abc", false),
        (b"1111111", true),
        (b"1222222", false),
    ];

    for (input, expected) in cases {
        let result = all_characters_same(input);
        println!(
            "all_characters_same({:?}) = {}, expected {}",
            *input, result, expected
        );
        assert_eq!(result, *expected);
    }
}